// Static render of the board front, from assets/pcb_front.json (generated by
// Android/tools/export_pcb_front.py from hardware/kicad/ESP-DubSiren.kicad_pcb).
// Port of PcbArt.kt. Coordinates are board millimetres; light from the top left.
import 'dart:convert';
import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

class _Pad {
  _Pad(this.plated, this.shape, this.x, this.y, this.w, this.h, this.rotation, this.drillW, this.drillH);
  final bool plated;
  final String shape;
  final double x, y, w, h, rotation, drillW, drillH;
}

class _Label {
  _Label(this.x, this.y, this.size, this.rotation, this.text);
  final double x, y, size, rotation;
  final String text;
}

double _f(dynamic v) => (v as num).toDouble();

Path _polyline(List<dynamic> points, {required bool close}) {
  final path = Path();
  if (points.length < 4) return path;
  path.moveTo(_f(points[0]), _f(points[1]));
  for (var i = 2; i + 1 < points.length; i += 2) {
    path.lineTo(_f(points[i]), _f(points[i + 1]));
  }
  if (close) path.close();
  return path;
}

/// Android BlurMaskFilter radius (device pixels) to a Skia sigma in board mm.
double _sigmaMm(double blurMm, double scale) => (blurMm * scale * 0.57735 + 0.5) / scale;

class PcbArt {
  PcbArt._(this._board, this._pour, this._tracks, this._vias, this._pads, this._silk, this._labels);

  final Path _board;
  final Path _pour;
  final List<List<double>> _tracks;
  final List<List<double>> _vias;
  final List<_Pad> _pads;
  final List<(double, Path)> _silk;
  final List<_Label> _labels;

  static Future<PcbArt> load() async {
    final json = jsonDecode(await rootBundle.loadString('assets/pcb_front.json')) as Map<String, dynamic>;
    final board = Path()..fillType = PathFillType.evenOdd;
    for (final loop in json['outline'] as List) {
      board.addPath(_polyline(loop as List, close: true), Offset.zero);
    }
    final pour = Path()..fillType = PathFillType.evenOdd;
    for (final zone in json['pour'] as List) {
      pour.addPath(_polyline(zone as List, close: true), Offset.zero);
    }
    List<double> floats(dynamic a) => [for (final v in a as List) _f(v)];
    return PcbArt._(
      board,
      pour,
      [for (final t in json['tracks'] as List) floats(t)],
      [for (final v in json['vias'] as List) floats(v)],
      [
        for (final p in json['pads'] as List)
          _Pad(p[0] != 'npth', p[1] as String, _f(p[2]), _f(p[3]), _f(p[4]), _f(p[5]), _f(p[6]), _f(p[7]),
              _f(p[8])),
      ],
      [for (final s in json['silk'] as List) (_f(s[0]), _polyline((s as List).sublist(1), close: false))],
      [for (final t in json['texts'] as List) _Label(_f(t[0]), _f(t[1]), _f(t[2]), _f(t[3]), t[5] as String)],
    );
  }

  // ---- Shadow helpers for elements baked into the background ----

  static Paint _shadowPaint(double blurMm, int alpha, double scale) => Paint()
    ..color = Color.fromARGB(alpha, 0, 0, 0)
    ..maskFilter = MaskFilter.blur(BlurStyle.normal, _sigmaMm(blurMm, scale));

  /// Soft contact shadow of a rounded rectangle, in board mm (canvas already scaled).
  static void shadowRoundRect(Canvas canvas, Rect rect, double radius, double dx, double dy, double blurMm,
      int alpha, double scale) {
    canvas.drawRRect(RRect.fromRectAndRadius(rect.shift(Offset(dx, dy)), Radius.circular(radius)),
        _shadowPaint(blurMm, alpha, scale));
  }

  static void shadowCircle(Canvas canvas, double x, double y, double r, double dx, double dy, double blurMm,
      int alpha, double scale) {
    canvas.drawCircle(Offset(x + dx, y + dy), r, _shadowPaint(blurMm, alpha, scale));
  }

  // ---- Board ----

  /// Draws the board into [canvas], already translated/scaled to board mm.
  void drawBoard(Canvas canvas, double scale) {
    // Cast shadow on the desk and the 1.6 mm FR4 edge seen from slightly in front.
    canvas.save();
    canvas.translate(1.4, 2.4);
    canvas.drawPath(_board, _shadowPaint(3.2, 170, scale));
    canvas.restore();
    canvas.save();
    canvas.translate(0.25, 0.9);
    canvas.drawPath(_board, Paint()..color = const Color(0xFF2E2C22)); // FR4 core under black mask
    canvas.restore();

    // Black matte soldermask over bare FR4.
    canvas.drawPath(
        _board,
        Paint()
          ..shader = ui.Gradient.linear(
              const Offset(0, -6), const Offset(86, 120), const [Color(0xFF161817), Color(0xFF070808)]));

    canvas.save();
    canvas.clipPath(_board);
    // Copper under the mask: GND pour and tracks read slightly lighter and raised.
    canvas.drawPath(_pour, Paint()..color = const Color(0xFF1A1E1C));
    final line = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round;
    for (final (pass, color, dx, dy) in const [
      (0, Color(0xFF050606), 0.06, 0.08),
      (1, Color(0xFF262C29), -0.04, -0.05),
      (2, Color(0xFF1D2220), 0.0, 0.0),
    ]) {
      line.color = color;
      for (final t in _tracks) {
        line.strokeWidth = t[0] + (pass == 2 ? -0.02 : 0);
        canvas.drawLine(Offset(t[1] + dx, t[2] + dy), Offset(t[3] + dx, t[4] + dy), line);
      }
    }
    // Tented vias: small domes under the mask.
    final dome = Paint();
    for (final v in _vias) {
      final r = v[2] / 2;
      dome.shader = ui.Gradient.radial(Offset(v[0] - r * 0.35, v[1] - r * 0.35), r * 1.3,
          const [Color(0xFF333A36), Color(0xFF101211)]);
      canvas.drawCircle(Offset(v[0], v[1]), r, dome);
    }
    // Gloss of the mask.
    canvas.drawRect(
        const Rect.fromLTRB(0, -6, 86, 120),
        Paint()
          ..shader = ui.Gradient.linear(
              const Offset(0, -6), const Offset(60, 70), const [Color(0x1AFFFFFF), Color(0x00FFFFFF)]));
    canvas.restore();

    _drawPads(canvas);
    _drawSilk(canvas, scale);
  }

  void _drawPads(Canvas canvas) {
    final gold = Paint();
    final hole = Paint();
    for (final pad in _pads) {
      canvas.save();
      canvas.translate(pad.x, pad.y);
      canvas.rotate(-pad.rotation * math.pi / 180);
      if (pad.plated) {
        // ENIG: warm gold, lit from the top left.
        gold.shader = ui.Gradient.linear(Offset(-pad.w / 2, -pad.h / 2), Offset(pad.w / 2, pad.h / 2),
            const [Color(0xFFF2D68E), Color(0xFF9C7634)]);
        final r = switch (pad.shape) {
          'circle' || 'oval' => math.min(pad.w, pad.h) / 2,
          'roundrect' => math.min(pad.w, pad.h) * 0.25,
          _ => 0.0,
        };
        canvas.drawRRect(
            RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: pad.w, height: pad.h),
                Radius.circular(r)),
            gold);
      }
      if (pad.drillW > 0) {
        // Through hole: the dark inside of the barrel, deeper towards the bottom right.
        hole.shader = ui.Gradient.radial(Offset(-pad.drillW * 0.15, -pad.drillH * 0.15),
            math.max(pad.drillW, pad.drillH) * 0.6, [
          pad.plated ? const Color(0xFF3A2E18) : const Color(0xFF1A1B1C),
          const Color(0xFF020202),
        ]);
        final r = math.min(pad.drillW, pad.drillH) / 2;
        canvas.drawRRect(
            RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: pad.drillW, height: pad.drillH),
                Radius.circular(r)),
            hole);
      }
      canvas.restore();
    }
  }

  void _drawSilk(Canvas canvas, double scale) {
    const inkColor = Color(0xFFE4E4DE);
    final ink = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..color = inkColor;
    for (final (width, path) in _silk) {
      ink.strokeWidth = width;
      canvas.drawPath(path, ink);
    }
    // Text laid out in pixels: tiny text sizes on a scaled canvas render poorly.
    for (final label in _labels) {
      final text = TextPainter(
        text: TextSpan(
          text: label.text,
          style: TextStyle(
              color: inkColor, fontSize: label.size / 0.72 * scale, fontWeight: FontWeight.bold), // KiCad size ~ cap height
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      canvas.save();
      canvas.translate(label.x, label.y);
      canvas.rotate(-label.rotation * math.pi / 180);
      canvas.scale(1 / scale, 1 / scale);
      // Centred like Paint.Align.CENTER with the baseline at size/2 below the anchor.
      final baseline = text.computeDistanceToActualBaseline(TextBaseline.alphabetic);
      text.paint(canvas, Offset(-text.width / 2, label.size * scale / 2 - baseline));
      text.dispose();
      canvas.restore();
    }
  }
}
